import 'dart:async';
import 'package:flutter/material.dart';
import 'package:logger/logger.dart';
import '../test_suite_interface.dart';
import '../testing_models.dart';
import '../../../utilities/logger.dart';

class EpicCashTestSuite implements TestSuiteInterface {
  final StreamController<TestSuiteStatus> _statusController = StreamController<TestSuiteStatus>.broadcast();
  TestSuiteStatus _status = TestSuiteStatus.waiting;

  @override
  String get displayName => "Epic Cash";

  @override
  Widget get icon => const Icon(Icons.currency_bitcoin, size: 32);

  @override
  TestSuiteStatus get status => _status;

  @override
  Stream<TestSuiteStatus> get statusStream => _statusController.stream;

  @override
  Future<TestResult> runTests() async {
    final stopwatch = Stopwatch()..start();
    final logs = <String>[];
    
    try {
      _updateStatus(TestSuiteStatus.running);
      
      logs.add("Starting Epic Cash test suite...");
      
      logs.add("Testing plugin connectivity verification...");
      await _testPluginConnectivity();
      logs.add("✓ Plugin connectivity test passed");
      
      logs.add("Testing wallet initialization...");
      await _testWalletInitialization();
      logs.add("✓ Wallet initialization test passed");
      
      logs.add("Testing Epic Cash specific validation...");
      await _testEpicCashValidation();
      logs.add("✓ Epic Cash validation test passed");
      
      stopwatch.stop();
      _updateStatus(TestSuiteStatus.passed);
      
      logs.add("All Epic Cash tests completed successfully!");
      
      return TestResult(
        success: true,
        message: "All Epic Cash tests passed",
        logs: logs,
        executionTime: stopwatch.elapsed,
      );
      
    } catch (e) {
      stopwatch.stop();
      _updateStatus(TestSuiteStatus.failed);
      
      logs.add("✗ Test failed: ${e.toString()}");
      
      return TestResult(
        success: false,
        message: "Epic Cash test failed: ${e.toString()}",
        logs: logs,
        executionTime: stopwatch.elapsed,
      );
    }
  }

  Future<void> _testPluginConnectivity() async {
    await Future.delayed(const Duration(milliseconds: 800));
  }

  Future<void> _testWalletInitialization() async {
    await Future.delayed(const Duration(milliseconds: 600));
  }

  Future<void> _testEpicCashValidation() async {
    await Future.delayed(const Duration(milliseconds: 700));
  }

  void _updateStatus(TestSuiteStatus newStatus) {
    _status = newStatus;
    _statusController.add(_status);
  }

  @override
  Future<void> cleanup() async {
    Logging.instance.log(Level.info, "Cleaning up Epic Cash test suite");
    _statusController.close();
  }
}